    tile = [row[::-1] for row in grid[::-1]]
    n = len(tile)
    def reflect(i):
        q = i % (2 * n)
        return q if q < n else 2 * n - 1 - q
    return [[tile[reflect(r)][reflect(c)] for c in range(3 * n)] for r in range(3 * n)]
def transform(grid):
    out = [row[:] for row in grid]
    n = len(grid)
    for c in range(len(grid[0])):
        if grid[n - 1][c] != 5:
            continue
        sources = [(r, grid[r][c]) for r in range(n) if grid[r][c] != 0]
        # In each gap, extend the color of the next source below; above the
        # highest source extend that topmost source's color.
        for r in range(n):
            if grid[r][c] != 0:
                continue
            below = next((color for sr, color in sources if sr > r), None)
            color = below if below is not None else sources[0][1]
            out[r][c] = color
